<?php
session_start();require_once __DIR__.'/dbconnection.php';if(($_SESSION['portal_role']??'')!=='admin'){http_response_code(403);exit('Access denied');}$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){$type=$_POST['type']??'';$amount=(float)($_POST['amount']??0);$date=$_POST['date']??date('Y-m-d');$patient=(int)($_POST['patientid']??0);$doctor=(int)($_POST['doctorid']??0);$desc=trim($_POST['description']??'');if($amount>0&&in_array($type,['patient_fee','other_income','other_expense'],true)){$s=$con->prepare("INSERT INTO financial_transactions(transaction_type,patientid,doctorid,amount,transaction_date,description) VALUES(?,?,?,?,?,?)");$s->bind_param('siidss',$type,$patient,$doctor,$amount,$date,$desc);$s->execute();$msg='Financial transaction recorded.';}}
$patients=$con->query("SELECT patientid,patientname FROM patient WHERE status='Active' ORDER BY patientname");$doctors=$con->query("SELECT doctorid,doctorname FROM doctor WHERE status='Active' ORDER BY doctorname");$income=(float)$con->query("SELECT COALESCE(SUM(amount),0) FROM financial_transactions WHERE transaction_type='patient_fee'")->fetch_row()[0];$salary=(float)$con->query("SELECT COALESCE(SUM(amount),0) FROM salary_payments")->fetch_row()[0];$net=$income-$salary;
?><!doctype html><html><head><meta charset="utf-8"><title>Finance</title><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"></head><body class="module-body"><div class="module-card"><div class="finance-head"><div><h1>Finance & Fees</h1><p class="muted">Track patient income, doctor salaries and the hospital balance.</p></div><div class="finance-total"><small>Net balance</small><b><?php echo number_format($net,2);?></b></div></div><?php if($msg):?><div class="success"><?php echo htmlspecialchars($msg);?></div><?php endif;?><div class="finance-cards"><div><small>Total patient fees</small><b><?php echo number_format($income,2);?></b></div><div><small>Total doctor salaries</small><b><?php echo number_format($salary,2);?></b></div><div><small>Net</small><b><?php echo number_format($net,2);?></b></div></div><h2>Record patient fee</h2><form method="post" class="form-grid"><input type="hidden" name="type" value="patient_fee"><label>Patient<select name="patientid"><option value="0">General / walk-in</option><?php while($p=$patients->fetch_assoc()):?><option value="<?php echo $p['patientid'];?>"><?php echo htmlspecialchars($p['patientname']);?></option><?php endwhile;?></select></label><label>Amount<input type="number" step="0.01" min="0" name="amount" required></label><label>Date<input type="date" name="date" value="<?php echo date('Y-m-d');?>"></label><label>Description<input name="description" placeholder="Consultation, treatment, room fee..."></label><button class="primary-btn">Record patient fee</button></form><hr><h2>Record other expense / income</h2><form method="post" class="form-grid"><label>Type<select name="type"><option value="other_income">Other income</option><option value="other_expense">Other expense</option></select></label><label>Doctor<select name="doctorid"><option value="0">None</option><?php while($d=$doctors->fetch_assoc()):?><option value="<?php echo $d['doctorid'];?>"><?php echo htmlspecialchars($d['doctorname']);?></option><?php endwhile;?></select></label><label>Amount<input type="number" step="0.01" min="0" name="amount" required></label><label>Date<input type="date" name="date" value="<?php echo date('Y-m-d');?>"></label><label>Description<input name="description"></label><button class="primary-btn">Save transaction</button></form></div></body></html>
